"use client"

import * as React from "react"
import { createPortal } from "react-dom"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Scrollbar } from "@/components/ui/scrollbar"
import { Sheet, SheetContent, SheetSpine, SheetTitle, SheetTrigger } from "@/components/ui/sheet"

/** The width at which the words fit beside the work. It is also in sidebar.css: a media query can't read a variable. */
const BREAKPOINT = 860
const WIDE = `(min-width: ${BREAKPOINT}px)`

/** true once the window is wide; null until the browser has said (the server and the first paint show both surfaces and let CSS choose). */
function useWide() {
  return React.useSyncExternalStore<boolean | null>(
    (notify) => {
      const query = matchMedia(WIDE)
      query.addEventListener("change", notify)
      return () => query.removeEventListener("change", notify)
    },
    () => matchMedia(WIDE).matches,
    () => null,
  )
}

/** Splits a group's name into the part that stays when the column is folded and the part that folds away: "VI Controls" keeps "VI", "Start" keeps "S". */
function split(label: string): { mark: string; rest: string; numeral: boolean } {
  const [first, ...more] = label.split(" ")
  if (more.length && /^[IVXLCDM]+$/.test(first)) return { mark: first, rest: more.join(" "), numeral: true }
  const [initial, ...rest] = Array.from(label)
  return { mark: initial ?? "", rest: rest.join(""), numeral: false }
}

/** Keep a word's initial when folded. Anything that isn't plain text is left alone. */
function fold(node: React.ReactNode): React.ReactNode {
  if (typeof node !== "string" || node.length < 2) return node
  const { mark, rest } = split(node)
  return (
    <>
      <span className="db-sidebar-i">{mark}</span>
      <span className="db-sidebar-rest">{rest}</span>
    </>
  )
}

/** What is being pointed at while folded: it gets its name in the margin, on a leader line. */
type Peek = { key: string; name: string; group: string; y: number; edge: number; rtl: boolean }
type Peeking = { peek: Peek | null; slot: HTMLElement | null; folded: boolean }
const PeekContext = React.createContext<Peeking>({ peek: null, slot: null, folded: false })

type SidebarProps = Omit<React.ComponentProps<"nav">, "aria-label"> & {
  /** Names the landmark: "Studio app", "Docs". */
  label: string
  /** The trigger's word, and the sheet's name, when the window is too narrow for the column. */
  sheetLabel?: string
  /** The column folds to a ruler: each group keeps its numeral or initial, each link a tick, and pointing at or focusing one draws its name (and a link's preview) in the margin. */
  folded?: boolean
  /** Smaller words, closer together: for a long index. */
  compact?: boolean
}

/**
 * A column of words beside the work. Wide, it stands inline; narrow, only a quiet trigger shows
 * and the same words open in a sheet. Choosing a link in the sheet puts it away.
 */
function Sidebar({ label, sheetLabel = "Index", folded, compact, className, children, onScroll, ...props }: SidebarProps) {
  const wide = useWide()
  const [open, setOpen] = React.useState(false)
  // Widening puts the sheet away, so it isn't waiting open when the window narrows again.
  const [was, setWas] = React.useState(wide)
  if (wide !== was) {
    setWas(wide)
    if (wide) setOpen(false)
  }

  // Pointing at a tick (or focusing it) names it in the margin. One callout is shared, and follows.
  const [peek, setPeek] = React.useState<Peek | null>(null)
  const [slot, setSlot] = React.useState<HTMLElement | null>(null)
  const [hushed, setHushed] = React.useState(false)
  const target = React.useRef<HTMLElement | null>(null)
  const callout = React.useRef<HTMLDivElement>(null)
  const list = React.useRef<HTMLDivElement>(null)
  const ruler = folded && wide !== false
  // Unfolding, or the window narrowing: nothing is pointed at any more.
  const [wasRuler, setWasRuler] = React.useState(ruler)
  if (ruler !== wasRuler) {
    setWasRuler(ruler)
    setPeek(null)
  }

  const look = (from: EventTarget | null) => {
    const el = from instanceof Element ? from.closest<HTMLElement>("[data-slot=sidebar-link], [data-slot=sidebar-label]") : null
    target.current = el
    const box = list.current
    if (!el || !box || !ruler) return setPeek(null)
    const r = el.getBoundingClientRect(), edge = box.getBoundingClientRect()
    const rtl = getComputedStyle(box).direction === "rtl"
    const link = el.dataset.slot === "sidebar-link"
    setPeek({
      key: link ? el.dataset.peekId! : "",
      name: el.dataset.name ?? el.textContent ?? "",
      group: link ? el.closest<HTMLElement>("[data-slot=sidebar-group]")?.dataset.name ?? "" : "",
      y: r.top + r.height / 2,
      edge: rtl ? edge.left : edge.right,
      rtl,
    })
  }

  // The callout sits beside its tick, kept inside the window; the leader line reaches back to the tick.
  React.useLayoutEffect(() => {
    const el = callout.current
    if (!el || !peek) return
    const place = () => {
      const name = el.querySelector<HTMLElement>("[data-slot=sidebar-callout-name]")
      const lead = name ? name.offsetTop + name.offsetHeight / 2 : 0
      const top = Math.max(8, Math.min(peek.y - lead, innerHeight - el.offsetHeight - 8))
      el.style.top = `${top}px`
      el.style.setProperty("--leader", `${peek.y - top}px`)
    }
    place()
    const watch = new ResizeObserver(place)
    watch.observe(el)
    return () => watch.disconnect()
  }, [peek])

  return (
    <nav
      data-slot="sidebar"
      aria-label={label}
      className={cn("db-sidebar db-scroll", className)}
      onScroll={(e) => {
        onScroll?.(e)
        if (target.current) look(target.current) // the tick moved under the pointer
      }}
      {...props}
    >
      {wide !== false && (
        <PeekContext.Provider value={{ peek, slot, folded: !!ruler }}>
          <div
            ref={list}
            data-slot="sidebar-list"
            data-folded={folded || undefined}
            data-compact={compact || undefined}
            className="db-sidebar-list"
            onPointerOver={(e) => {
              if (e.pointerType === "touch") return
              setHushed(false)
              look(e.target)
            }}
            onPointerLeave={() => !list.current?.contains(document.activeElement) && look(null)}
            onFocus={(e) => {
              setHushed(false)
              look(e.target.matches(":focus-visible") ? e.target : null)
            }}
            onBlur={(e) => !list.current?.contains(e.relatedTarget as Node | null) && look(null)}
            onKeyDown={(e) => e.key === "Escape" && peek && setHushed(true)}
          >
            {children}
          </div>
          {ruler && peek && !hushed && (
            <div
              ref={callout}
              key={peek.key || peek.name}
              data-slot="sidebar-callout"
              data-rtl={peek.rtl || undefined}
              aria-hidden="true"
              className="db-sidebar-callout"
              style={peek.rtl ? { right: innerWidth - peek.edge } : { left: peek.edge }}
            >
              <p data-slot="sidebar-callout-name" className="db-sidebar-callout-name">{peek.name}</p>
              {peek.group ? <p className="db-sidebar-callout-group">{peek.group}</p> : null}
              <div ref={setSlot} className="db-sidebar-callout-preview" />
            </div>
          )}
        </PeekContext.Provider>
      )}
      <Sheet open={open} onOpenChange={setOpen}>
        {wide !== true && (
          <SheetTrigger asChild>
            <Button variant="quiet" data-slot="sidebar-trigger">{sheetLabel}</Button>
          </SheetTrigger>
        )}
        {wide === false && (
          <SheetContent side="start" className="db-sidebar-sheet">
            <SheetSpine>{sheetLabel}</SheetSpine>
            <SheetTitle className="db-sr">{sheetLabel}</SheetTitle>
            <div
              data-slot="sidebar-list"
              data-compact={compact || undefined}
              className="db-sidebar-list"
              onClick={(e) => {
                if ((e.target as Element).closest("a[href]")) setOpen(false)
              }}
            >
              {children}
            </div>
          </SheetContent>
        )}
      </Sheet>
      <Scrollbar />
    </nav>
  )
}

/** The column's own name, at the top. Folded, it too keeps its initial. */
function SidebarHead({ className, children, ...props }: React.ComponentProps<"p">) {
  return (
    <p data-slot="sidebar-head" className={cn("db-sidebar-head", className)} {...props}>
      {fold(children)}
    </p>
  )
}

type SidebarGroupProps = Omit<React.ComponentProps<"div">, "aria-labelledby"> & {
  /** What the links share: a movement ("VI Controls"), a section. Folded, a leading roman numeral stays ("VI"), or else the initial. */
  label: string
}

function SidebarGroup({ label, className, children, ...props }: SidebarGroupProps) {
  const id = React.useId()
  const { mark, rest, numeral } = split(label)
  return (
    <div data-slot="sidebar-group" data-name={label} className={cn("db-sidebar-group", className)} {...props}>
      <p id={id} data-slot="sidebar-label" data-name={label} className="db-sidebar-label">
        <span className="db-sidebar-i">{mark}</span>
        {numeral ? " " : null}
        <span className="db-sidebar-rest" data-numeral={numeral || undefined}>{rest}</span>
      </p>
      <ul aria-labelledby={id} className="db-sidebar-links">{children}</ul>
    </div>
  )
}

type SidebarLinkProps = React.ComponentProps<"a"> & {
  /** The page you are on: it carries the accent dot. */
  current?: boolean
  /** Render the child (a framework's Link) with the sidebar's look. */
  asChild?: boolean
  /** Shown beside the tick, under its name, while the column is folded and the link is pointed at or focused: a sentence about where it goes. */
  preview?: React.ReactNode
}

function SidebarLink({ current, asChild = false, preview, className, children, ...props }: SidebarLinkProps) {
  const Comp = asChild ? Slot : "a"
  const id = React.useId()
  const { peek, slot } = React.useContext(PeekContext)
  // The word sits in its own box so folding can take it away and leave the name for assistive technology.
  const word = (node: React.ReactNode) => <span className="db-sidebar-text">{node}</span>
  const label = asChild && React.isValidElement<{ children?: React.ReactNode }>(children) ? React.cloneElement(children, undefined, word(children.props.children)) : word(children)
  return (
    <li data-slot="sidebar-item" className="db-sidebar-item">
      <Comp data-slot="sidebar-link" data-peek-id={id} data-peeked={peek?.key === id || undefined} aria-current={current ? "page" : undefined} className={cn("db-sidebar-link", className)} {...props}>
        {label}
      </Comp>
      {preview && slot && peek?.key === id ? createPortal(preview, slot) : null}
    </li>
  )
}

export { Sidebar, SidebarHead, SidebarGroup, SidebarLink, type SidebarProps }

@layer components {
  /* ── db-sidebar ── a column of words; folded, a ruler: each group keeps its numeral, each link a tick.
     Wide, the words stand inline. Narrow, only the trigger shows and the same words open in a sheet.
     860px is the docs frame's breakpoint and BREAKPOINT in sidebar.tsx: keep them equal.
     The nav is the scroller (give it a height); its rail runs down the column's own rule. */
  /* Registered, so each link's place is worked out on the link and inherited by its words. */
  @property --db-sidebar-i { syntax: "<integer>"; inherits: true; initial-value: 0; }
  .db-sidebar { font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-sidebar.db-scroll { overflow-x: hidden; }
  .db-sidebar > .db-scrollbar { --line: 0; } /* the thumb rides the column's own hairline */
  .db-sidebar-list {
    display: grid; align-content: start; justify-items: start; gap: var(--db-space-1);
    font-size: var(--db-mp); line-height: var(--db-mp-lh);
  }
  /* Compact: a size down, and the links close up. */
  .db-sidebar-list[data-compact] { font-size: var(--db-p); line-height: var(--db-p-lh); }
  .db-sidebar-list[data-compact] :is(.db-sidebar-group, .db-sidebar-links) { gap: 0; }
  .db-sidebar-list[data-compact] :is(.db-sidebar-group + .db-sidebar-group, .db-sidebar-head + .db-sidebar-group) { margin-block-start: var(--db-space-5); }
  .db-sidebar > .db-sidebar-list { padding-inline-end: var(--db-space-6); border-inline-end: var(--db-hairline) solid var(--db-rule); }
  /* Before the browser has said how wide it is, both surfaces are in the page and CSS chooses. */
  @media (min-width: 860px) { .db-sidebar > [data-slot="sidebar-trigger"] { display: none; } }
  @media (max-width: 859.98px) { .db-sidebar > .db-sidebar-list { display: none; } }
  .db-sheet.db-sidebar-sheet { width: min(20rem, calc(100vw - var(--db-space-6))); }
  .db-sidebar-head { margin-block-end: var(--db-space-4); font-weight: 600; color: var(--db-ink); white-space: nowrap; }
  .db-sidebar-group { display: grid; justify-items: start; gap: var(--db-space-1); }
  .db-sidebar-group + .db-sidebar-group, .db-sidebar-head + .db-sidebar-group { margin-block-start: var(--db-space-4); }
  .db-sidebar-label { font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); white-space: nowrap; font-variant-numeric: tabular-nums; transition: color var(--db-allegro); }
  .db-sidebar-links { display: grid; justify-items: start; gap: var(--db-space-1); margin: 0; padding: 0; list-style: none; }
  .db-sidebar-item { --db-sidebar-i: sibling-index(); }
  .db-sidebar-link {
    position: relative; display: flex; align-items: baseline; padding-inline-start: 1em;
    color: var(--db-graphite); text-decoration: none; white-space: nowrap; transition: color var(--db-allegro);
  }
  .db-sidebar-link:is(:hover, [data-force~="hover"], [data-peeked]), .db-sidebar-link[aria-current="page"] { color: var(--db-ink); }
  .db-sidebar-link::before {
    content: ""; position: absolute; inset-inline-start: 0; top: calc(50% - 3px); width: 6px; height: 6px; border-radius: 50%;
    background: var(--db-accent); scale: 0;
    transition: scale var(--db-moderato) var(--db-spiccato), background-color var(--db-allegro), box-shadow var(--db-allegro);
  }
  .db-sidebar-link:is(:hover, [data-force~="hover"], [data-peeked]):not([aria-current="page"])::before { scale: 1; background-color: transparent; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  .db-sidebar-link[aria-current="page"]::before { scale: 1; }

  /* Folding: the words fold away in turn, and what is left is a ruler. The name stays in the page for assistive technology. */
  .db-sidebar-text, .db-sidebar-rest {
    display: inline-block; overflow: clip; width: auto; vertical-align: bottom;
    transition: width var(--db-andante) var(--db-exhale), opacity var(--db-moderato); transition-delay: calc(var(--db-sidebar-i) * var(--db-arpeggio));
  }
  .db-sidebar-list[data-folded] :is(.db-sidebar-text, .db-sidebar-rest) { width: 0; opacity: 0; }
  .db-sidebar-list[data-folded] .db-sidebar-head { color: var(--db-ink); }

  /* The ruler: a hairline down the column's inline end, a numeral for each group, a tick for each link.
     The tick stretches when pointed at; the page you are on has the longest, with the dot at its far end. */
  .db-sidebar > .db-sidebar-list[data-folded] { inline-size: var(--db-sidebar-rail, 3rem); padding-inline-end: 0; justify-items: stretch; }
  .db-sidebar-list[data-folded] :is(.db-sidebar-group, .db-sidebar-links) { justify-items: stretch; }
  .db-sidebar-list[data-folded][data-compact] :is(.db-sidebar-group + .db-sidebar-group, .db-sidebar-head + .db-sidebar-group) { margin-block-start: var(--db-space-3); }
  .db-sidebar-list[data-folded] .db-sidebar-label { padding-inline-start: var(--db-space-1); }
  .db-sidebar-list[data-folded] .db-sidebar-group:has([aria-current="page"]) .db-sidebar-label { color: var(--db-ink); }
  .db-sidebar-link::after {
    content: ""; position: absolute; inset-inline-end: 0; top: 50%; width: 0; height: var(--db-hairline); background: var(--db-rule-strong);
    transition: width var(--db-moderato) var(--db-exhale), background-color var(--db-allegro); transition-delay: calc(var(--db-sidebar-i) * var(--db-arpeggio)), 0s;
  }
  .db-sidebar-list[data-folded] .db-sidebar-link {
    --tick: 0.5rem; inline-size: 100%; min-block-size: 1.5rem; padding-inline: 0; align-items: center;
  }
  .db-sidebar-list[data-folded] .db-sidebar-link::after { width: var(--tick); }
  .db-sidebar-list[data-folded] .db-sidebar-link:is(:hover, [data-force~="hover"], [data-peeked], [aria-current="page"]) { --tick: 1rem; }
  .db-sidebar-list[data-folded] .db-sidebar-link:is(:hover, [data-force~="hover"], [data-peeked], [aria-current="page"])::after { background: var(--db-ink); }
  .db-sidebar-list[data-folded] .db-sidebar-link::before { inset-inline: auto calc(var(--tick) - 3px); transition-property: scale, background-color, box-shadow, inset-inline-end; }
  .db-sidebar-list[data-folded] .db-sidebar-link:focus-visible { outline-offset: -2px; }

  /* The name comes out into the margin on a leader line, with what the link is beneath it. It is one element,
     placed by the script beside whatever is pointed at; it never takes the pointer. */
  .db-sidebar-callout {
    position: fixed; z-index: 45; display: grid; justify-items: start; gap: 0.2rem; inline-size: max-content; max-inline-size: min(22rem, 60vw);
    padding: 0.2rem var(--db-space-3) 0.4rem var(--db-space-6); background: var(--db-paper); pointer-events: none;
    font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-graphite);
  }
  .db-sidebar-callout::before {
    content: ""; position: absolute; inset-inline-start: 0; top: var(--leader, 0.9rem); width: var(--db-space-5); height: var(--db-hairline); background: var(--db-ink);
    transform-origin: 0 50%; animation: db-draw-x var(--db-allegro) var(--db-exhale) backwards;
  }
  .db-sidebar-callout:is([dir="rtl"], [dir="rtl"] *)::before, .db-sidebar-callout[data-rtl]::before { transform-origin: 100% 50%; }
  .db-sidebar-callout-name { font-size: var(--db-mp); line-height: var(--db-mp-lh); letter-spacing: var(--db-mp-tr); font-weight: 400; color: var(--db-ink); white-space: nowrap; }
  .db-sidebar-callout-group { color: var(--db-pencil); font-variant-numeric: tabular-nums; }
  .db-sidebar-callout-preview:not(:empty) { max-inline-size: 30ch; margin-block-start: 0.2rem; animation: db-arrive var(--db-moderato) var(--db-exhale) 380ms backwards; }
}
